function getCyberarkTranslation(key, lang) {
    return (cyberarkTranslations[lang] && cyberarkTranslations[lang][key]) ||
           (cyberarkTranslations.en && cyberarkTranslations.en[key]) || null;
}

function applyCyberarkTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.cyberark.") || key.startsWith("review.common."))) {
            const translation = getCyberarkTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyCyberarkTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyCyberarkTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyCyberarkTranslations(window.i18n?.getCurrentLanguage() || "en");
}
